+import Yoga from 'yoga-layout';
+import {type DOMElement, type DOMNode} from './dom.js';
+
+type Track =
+	| {kind: 'fixed'; size: number}
+	| {kind: 'fr'; fraction: number; minimum: number}
+	| {kind: 'auto'};
+
+type Placement = {start?: number; end?: number};
+type Item = {node: DOMNode; column: Placement; row: Placement};
+
+const trackPattern = /minmax\\(\\s*\\d+(?:\\.\\d+)?\\s*,\\s*(?:\\d+(?:\\.\\d+)?|\\d*(?:\\.\\d+)?fr)\\s*\\)|\\d*(?:\\.\\d+)?fr|auto|\\d+(?:\\.\\d+)?/g;
+
+const parseTracks = (value: string | undefined): Track[] => {
+	const tokens = value?.match(trackPattern) ?? ['auto'];
+	return tokens.map(token => {
+		if (token === 'auto') return {kind: 'auto'};
+		if (token.startsWith('minmax(')) {
+			const [minimum, maximum] = token.slice(7, -1).split(',').map(part => part.trim());
+			if (maximum.endsWith('fr')) {
+				return {
+					kind: 'fr',
+					minimum: Number(minimum),
+					fraction: Number.parseFloat(maximum) || 1,
+				};
+			}
+
+			return {kind: 'fixed', size: Number(maximum)};
+		}
+
+		if (token.endsWith('fr')) {
+			return {kind: 'fr', minimum: 0, fraction: Number.parseFloat(token) || 1};
+		}
+
+		return {kind: 'fixed', size: Number(token)};
+	});
+};
+
+const parsePlacement = (value: number | string | undefined): Placement => {
+	if (typeof value === 'number') return {start: value, end: value + 1};
+	if (!value) return {};
+	const match = /^(\\d+)\\s*\\/\\s*(\\d+)$/.exec(value);
+	return match ? {start: Number(match[1]), end: Number(match[2])} : {};
+};
+
+const gapFor = (node: DOMElement, direction: 'column' | 'row'): number =>
+	direction === 'column'
+		? node.style.columnGap ?? node.style.gap ?? 0
+		: node.style.rowGap ?? node.style.gap ?? 0;
+
+const gridChildren = (node: DOMElement): DOMNode[] =>
+	node.childNodes.filter(child => child.yogaNode && child.style.display !== 'none');
+
+const prepareGrid = (node: DOMElement): void => {
+	if (node.style.display === 'grid') {
+		for (const child of gridChildren(node)) {
+			child.yogaNode!.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
+		}
+	}
+
+	for (const child of node.childNodes) {
+		if (child.yogaNode) prepareGrid(child as DOMElement);
+	}
+};
+
+const resolveTracks = (tracks: Track[], available: number, gap: number, autoSizes: number[]): number[] => {
+	const base = tracks.map((track, index) =>
+		track.kind === 'fixed' ? track.size : track.kind === 'auto' ? autoSizes[index] ?? 0 : track.minimum,
+	);
+	const remaining = Math.max(0, available - base.reduce((sum, size) => sum + size, 0) - Math.max(0, tracks.length - 1) * gap);
+	const fractions = tracks.reduce((sum, track) => sum + (track.kind === 'fr' ? track.fraction : 0), 0);
+	return base.map((size, index) => tracks[index]!.kind === 'fr' && fractions > 0 ? size + remaining * tracks[index]!.fraction / fractions : size);
+};
+
+const locateItems = (children: DOMNode[], columnCount: number): Item[] => {
+	const items = children.map(node => ({node, column: parsePlacement(node.style.gridColumn), row: parsePlacement(node.style.gridRow)}));
+	const occupied = new Set<string>();
+	const mark = (item: Item) => {
+		for (let row = item.row.start!; row < item.row.end!; row++) for (let column = item.column.start!; column < item.column.end!; column++) occupied.add(`${row}:${column}`);
+	};
+	for (const item of items) if (item.column.start && item.row.start) mark(item);
+
+	let cursor = 1;
+	for (const item of items) {
+		if (item.column.start && item.row.start) continue;
+		const columnSpan = (item.column.end ?? (item.column.start ? item.column.start + 1 : 1)) - (item.column.start ?? 1);
+		const rowSpan = (item.row.end ?? (item.row.start ? item.row.start + 1 : 1)) - (item.row.start ?? 1);
+		let row = item.row.start ?? 1;
+		let column = item.column.start ?? cursor;
+		while ([...Array(rowSpan)].some((_, rowOffset) => [...Array(columnSpan)].some((_, columnOffset) => column + columnOffset > columnCount || occupied.has(`${row + rowOffset}:${column + columnOffset}`)))) {
+			if (item.column.start) row++; else if (++column > columnCount) { column = 1; row++; }
+		}
+		item.column = {start: column, end: column + columnSpan};
+		item.row = {start: row, end: row + rowSpan};
+		mark(item);
+		cursor = column + columnSpan;
+		if (cursor > columnCount) cursor = 1;
+	}
+
+	return items;
+};
+
+const layoutGrid = (node: DOMElement): void => {
+	const yogaNode = node.yogaNode!;
+	const children = gridChildren(node);
+	const columns = parseTracks(node.style.gridTemplateColumns);
+	const items = locateItems(children, columns.length);
+	const columnGap = gapFor(node, 'column');
+	const rowGap = gapFor(node, 'row');
+	const autoColumnSizes = columns.map((_, index) => Math.max(0, ...items.filter(item => item.column.end! - item.column.start! === 1 && item.column.start === index + 1).map(item => item.node.yogaNode!.getComputedWidth())));
+	const columnSizes = resolveTracks(columns, yogaNode.getComputedWidth(), columnGap, autoColumnSizes);
+	const rowCount = Math.max(0, ...items.map(item => item.row.end! - 1));
+	const rows = parseTracks(node.style.gridTemplateRows);
+	while (rows.length < rowCount) rows.push({kind: 'auto'});
+
+	const columnOffsets = columnSizes.reduce<number[]>((offsets, size) => [...offsets, (offsets.at(-1) ?? 0) + size + columnGap], []).slice(0, -1);
+	for (const item of items) {
+		const start = item.column.start! - 1;
+		const end = item.column.end! - 1;
+		item.node.yogaNode!.setPosition(Yoga.EDGE_LEFT, columnOffsets[start] ?? 0);
+		item.node.yogaNode!.setWidth(columnSizes.slice(start, end).reduce((sum, size) => sum + size, 0) + Math.max(0, end - start - 1) * columnGap);
+	}
+
+	const autoRowSizes = rows.map((_, index) => Math.max(0, ...items.filter(item => item.row.end! - item.row.start! === 1 && item.row.start === index + 1).map(item => item.node.yogaNode!.getComputedHeight())));
+	const rowSizes = resolveTracks(rows, yogaNode.getComputedHeight(), rowGap, autoRowSizes);
+	const rowOffsets = rowSizes.reduce<number[]>((offsets, size) => [...offsets, (offsets.at(-1) ?? 0) + size + rowGap], []).slice(0, -1);
+	for (const item of items) {
+		const start = item.row.start! - 1;
+		const end = item.row.end! - 1;
+		item.node.yogaNode!.setPosition(Yoga.EDGE_TOP, rowOffsets[start] ?? 0);
+		item.node.yogaNode!.setHeight(rowSizes.slice(start, end).reduce((sum, size) => sum + size, 0) + Math.max(0, end - start - 1) * rowGap);
+	}
+
+	if (node.style.height === undefined) yogaNode.setHeight(rowSizes.reduce((sum, size) => sum + size, 0) + Math.max(0, rowSizes.length - 1) * rowGap);
+};
+
+const layoutGrids = (node: DOMElement): void => {
+	if (node.style.display === 'grid') layoutGrid(node);
+	for (const child of node.childNodes) if (child.yogaNode) layoutGrids(child as DOMElement);
+};
+
+export const calculateGridLayout = (rootNode: DOMElement, width: number): void => {
+	rootNode.yogaNode!.setWidth(width);
+	prepareGrid(rootNode);
+	for (let pass = 0; pass < 3; pass++) {
+		rootNode.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+		layoutGrids(rootNode);
+	}
+	rootNode.yogaNode!.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
+};
